def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    s = text(tt)
    if 'clean' in s:
        return 'clean'
    if 'heat' in s:
        return 'heat'
    if 'cool' in s:
        return 'cool'
    if 'slice' in s:
        return 'slice'
    return ''

def hook(ctx, nb):
    tt = getv(ctx, 'task.task_type', '')
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['carrying_target'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['carrying_target'] = False
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = getv(ctx, 'world.placed_locations', [])
    if isinstance(locs, (list, tuple, set)):
        locs_text = ' '.join([text(i) for i in locs])
    else:
        locs_text = text(locs)
    if locs_text and locs_text not in nb.get('placed_locations_text', ''):
        nb['placed_locations_text'] = nb.get('placed_locations_text', '') + ' ' + locs_text
    carrying = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and target and target not in inv and 'not carrying' not in inv and 'nothing' not in inv)
    if wrong:
        stage = 'wrong_inventory'
    elif carrying:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        else:
            stage = 'put_target'
    else:
        if 'two' in text(tt) and nb.get('placed_count', 0) > 0:
            stage = 'find_target'
        elif getv(ctx, 'world.target_found', False) or getv(ctx, 'world.target_location', ''):
            stage = 'take_target'
        else:
            stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_verb'] = verb
    return None

