def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('transform_verb') or ''
    tt = nb.get('task_type') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the target type. Do not place it at the destination; recover by setting it aside only if needed, then find the target.'
    elif stage == 'transform' and verb:
        msg = 'You are carrying the target. Use the admissible ' + verb + ' action before placing it; do not search or examine other places.'
    elif stage == 'put_target':
        if 'two' in text(tt) and nb.get('placed_count', 0) > 0:
            msg = 'You are carrying another target. Put it at the same destination used for the first one, then continue only if a second item is still needed.'
        else:
            msg = 'You are carrying the target. Go to the ' + dest + ' and use the admissible put action there; do not keep searching.'
    elif stage == 'take_target':
        msg = 'The target is available. Take the target instead of examining or using unrelated objects.'
    elif stage == 'find_target' and 'two' in text(tt) and nb.get('placed_count', 0) > 0:
        msg = 'One target is already placed. Leave it there, find another target of the same type, and return to the same destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

