def hook(ctx, nb):
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(nb.get('task_type') or getv(ctx, 'task.task_type', ''))
    stage = nb.get('stage', '')
    tt = nb.get('task_type') or text(getv(ctx, 'task.task_type', ''))
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act or not target:
        return None
    carrying = bool(target in text(getv(ctx, 'world.inventory', '')))
    if not carrying and not nb.get('carrying_target') and stage in ('transform', 'put_target'):
        return None
    if stage == 'transform' and verb and not nb.get('transformed'):
        if act.startswith('put ') or act.startswith('examine ') or act.startswith('use '):
            return {'kind': 'block_and_prompt', 'message': 'The target still needs the required ' + verb + ' step. Choose an admissible transform action for the target before placing or examining.'}
    if stage == 'put_target' and dest and act.startswith('put ') and target in act and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Carry the target to the ' + dest + ' and put it there.'}
    if stage == 'put_target' and dest and act.startswith('put ') and target in act and dest in act and not nb.get('transformed') and verb:
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First perform the required ' + verb + ' action, then put it at the destination.'}
    if 'two' in text(tt) and nb.get('placed_count', 0) > 0 and act.startswith('take ') and target in act:
        locs = nb.get('placed_locations_text', '')
        if locs and locs in act:
            return {'kind': 'block_and_prompt', 'message': 'Do not take back an already placed target. Find another target of the same type for the same destination.'}
    if stage == 'find_target' and 'two' in text(tt) and nb.get('placed_count', 0) > 0 and act.startswith('put ') and target in act and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'One target is already placed at this destination. Leave it there and search for another target instead.'}
    return None
